#include "s61_binary_deeper_quartic_field_20261101.hpp"
#include <chrono>
int main(int argc,char**argv){assert(argc==5);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]),fi(argv[2]);ofstream out(argv[4]);int choose=stoi(argv[3]),nf;fi>>nf;assert(choose<nf);Rat G;for(int j=0;j<=choose;j++)readpoly(fi,G.n);Rat ca,cb,z;fmpq_mpoly_gen(z.n,1,ctx);fmpq_t c;fmpq_init(c);ulong ex[2];for(int k=0;k<fmpq_mpoly_length(G.n,ctx);k++){fmpq_mpoly_get_term_exp_ui(ex,G.n,k,ctx);assert(ex[1]<=1);int power=ex[1];ex[1]=0;fmpq_mpoly_get_term_coeff_fmpq(c,G.n,k,ctx);fmpq_mpoly_push_term_fmpq_ui(power?cb.n:ca.n,c,ex,ctx);}for(auto p:{ca.n,cb.n}){fmpq_mpoly_sort_terms(p,ctx);fmpq_mpoly_combine_like_terms(p,ctx);}assert(!cb.zero());Rat image;fmpq_mpoly_sub(image.n,z.n,ca.n,ctx);int n,m;in>>n>>m;out<<n<<' '<<m<<'\n';auto start=chrono::steady_clock::now();map<pair<int,int>,Rat>powers;long total=0;for(int i=0;i<n;i++){int nn;in>>nn;Row row;int md=0;for(int k=0;k<nn;k++){int j;Rat a;in>>j;readpoly(in,a.n);md=max(md,int(fmpq_mpoly_degree_si(a.n,1,ctx)));row.emplace(j,std::move(a));}for(int k=0;k<=md;k++)if(!powers.count({md,k})){Rat a,b;fmpq_mpoly_pow_ui(a.n,image.n,k,ctx);fmpq_mpoly_pow_ui(b.n,cb.n,md-k,ctx);fmpq_mpoly_mul(powers[{md,k}].n,a.n,b.n,ctx);}out<<nn<<'\n';for(auto&[j,a]:row){vector<Rat>coeff(md+1);for(long k=0;k<fmpq_mpoly_length(a.n,ctx);k++){fmpq_mpoly_get_term_exp_ui(ex,a.n,k,ctx);int power=ex[1];ex[1]=0;fmpq_mpoly_get_term_coeff_fmpq(c,a.n,k,ctx);fmpq_mpoly_push_term_fmpq_ui(coeff[power].n,c,ex,ctx);}Rat sum,tmp;for(int k=0;k<=md;k++){fmpq_mpoly_sort_terms(coeff[k].n,ctx);fmpq_mpoly_combine_like_terms(coeff[k].n,ctx);fmpq_mpoly_mul(tmp.n,coeff[k].n,powers[{md,k}].n,ctx);fmpq_mpoly_add(sum.n,sum.n,tmp.n,ctx);}assert(!sum.zero());out<<j<<'\n';writepoly(out,sum.n);total+=fmpq_mpoly_length(sum.n,ctx);}if(i%50==0)cerr<<"ROW "<<i<<" TERMS "<<total<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}fmpq_clear(c);cerr<<"SHIFT_EXACT "<<choose<<" TERMS "<<total<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
